def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def info(p):
 p=Path(p); p=p if p.is_absolute() else ROOT/p
 im=Image.open(p); a=im.getchannel('A') if 'A' in im.getbands() else None
 out={'path':str(p),'repoRelativePath':str(p.relative_to(ROOT)) if p.is_relative_to(ROOT) else None,'sha256':sha(p),'dimensions':list(im.size),'mode':im.mode,'alphaExtrema':list(a.getextrema()) if a else None}
 if a:
  hist=a.histogram(); w,h=im.size
  edges=[a.getpixel((x,y)) for y in (0,h-1) for x in range(w)]+[a.getpixel((x,y)) for x in (0,w-1) for y in range(1,h-1)]
  out.update(transparentFraction=hist[0]/(w*h),edgeMaxAlpha=max(edges),nearOpaqueCore=bool(sum(hist[240:])))
 return out

def evidence(path,start,end=None):
 lines=(ROOT/path).read_text().splitlines(); end=end or start
 return {'path':str(path),'startLine':start,'endLine':end,'originalText':'\n'.join(lines[start-1:end])}
def matched_line(path,needle):
 for i,l in enumerate((ROOT/path).read_text().splitlines(),1):
  if needle in l:return evidence(path,i)
 raise ValueError((path,needle))

